import"./chunk-VC46IEJQ.js";var e=(t,o,a,n,s,r,h,i,l,d,f={})=>({id:t,kind:o,region:"vale",at:a,rank:n,names:s,alt:r,summary:h,houses:i,refs:l,confidence:d,...f}),c={group:"vale",places:[{id:"the-eyrie",houses:["arryn"],refs:["agot","asos","affc","twoiaf"],confidence:"high",summary:{en:"Seat of House Arryn, a small castle of white stone set on a shoulder of the Giant's Lance, thousands of feet above the valley floor. No army has ever taken it by force; the way up is a narrow stair past three waycastles, and in winter the household moves down to the Gates of the Moon. Its sky cells and Moon Door give it a fearsome reputation.",zh:"\u827E\u6797\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4E00\u5EA7\u767D\u77F3\u5C0F\u57CE\uFF0C\u5750\u843D\u4E8E\u5DE8\u4EBA\u4E4B\u67AA\u7684\u5C71\u80A9\uFF0C\u9AD8\u51FA\u8C37\u5E95\u6570\u5343\u5C3A\u3002\u4ECE\u672A\u6709\u519B\u961F\u4EE5\u6B66\u529B\u653B\u514B\u6B64\u57CE\uFF1B\u4E0A\u5C71\u53EA\u6709\u4E00\u6761\u9014\u7ECF\u4E09\u5EA7\u4E2D\u9014\u5821\u7684\u72ED\u7A84\u77F3\u9636\uFF0C\u5165\u51AC\u540E\u5168\u5BB6\u4FBF\u8FC1\u5F80\u5C71\u811A\u7684\u6708\u95E8\u5821\u3002\u57CE\u4E2D\u7684\u5929\u7262\u4E0E\u201C\u6708\u95E8\u201D\u4EE4\u4EBA\u95FB\u4E4B\u8272\u53D8\u3002"},spoiler:{en:"Lysa Arryn falls to her death through the Moon Door, pushed by Petyr Baelish (A Storm of Swords).",zh:"\u83B1\u838E\xB7\u827E\u6797\u88AB\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\u63A8\u51FA\u6708\u95E8\uFF0C\u5760\u5D16\u8EAB\u4EA1\uFF08\u5377\u4E09\uFF09\u3002"}},{id:"gulltown",houses:["grafton","shett","arryn-of-gulltown"],refs:["agot","affc","twoiaf"],confidence:"high",summary:{en:"The Vale's one true city and chief harbour, on the southern coast where the valley opens onto the Bay of Crabs and the Narrow Sea. It is held for the Arryns by House Grafton, and its ships trade with Braavos, Pentos and the other Free Cities.",zh:"\u8C37\u5730\u552F\u4E00\u771F\u6B63\u7684\u57CE\u5E02\u548C\u9996\u8981\u6E2F\u53E3\uFF0C\u4F4D\u4E8E\u5C71\u8C37\u5357\u7AEF\u4E34\u6D77\u4E4B\u5904\uFF0C\u9762\u5411\u8783\u87F9\u6E7E\u4E0E\u72ED\u6D77\u3002\u845B\u62C9\u592B\u987F\u5BB6\u65CF\u4EE3\u827E\u6797\u5BB6\u65CF\u9547\u5B88\u6B64\u57CE\uFF0C\u5546\u8239\u5F80\u6765\u4E8E\u5E03\u62C9\u4F5B\u65AF\u3001\u6F58\u6258\u65AF\u7B49\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u3002"}},e("gates-of-the-moon","castle",[490,802],3,{en:"Gates of the Moon",zh:"\u6708\u95E8\u5821"},["Gates","\u6708\u95E8"],{en:"A strong castle at the foot of the Giant's Lance, guarding the start of the climb to the Eyrie. Its castellans are a cadet branch of House Royce, and the Arryn household winters here when the high road to the Eyrie becomes too dangerous.",zh:"\u5DE8\u4EBA\u4E4B\u67AA\u5C71\u811A\u4E0B\u4E00\u5EA7\u575A\u56FA\u7684\u57CE\u5821\uFF0C\u627C\u5B88\u6500\u5F80\u9E70\u5DE2\u57CE\u7684\u8D77\u70B9\u3002\u57CE\u4E3B\u7531\u7F57\u4F0A\u65AF\u5BB6\u65CF\u7684\u652F\u7CFB\u62C5\u4EFB\uFF1B\u6BCF\u5F53\u51AC\u5B63\u4E0A\u5C71\u4E4B\u8DEF\u9669\u4E0D\u53EF\u884C\uFF0C\u827E\u6797\u5BB6\u65CF\u4FBF\u79FB\u5C45\u4E8E\u6B64\u8FC7\u51AC\u3002"},["royce-gates-of-the-moon","arryn"],["agot","affc"],"high",{spoiler:{en:'Petyr Baelish makes Ser Nestor Royce hereditary Keeper of the Gates of the Moon, and Sansa, as "Alayne Stone", winters here (A Feast for Crows).',zh:"\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\u5C01\u5948\u65AF\u7279\xB7\u7F57\u4F0A\u65AF\u7235\u58EB\u4E3A\u4E16\u88AD\u7684\u6708\u95E8\u5821\u5B88\u62A4\uFF1B\u5316\u540D\u201C\u4E9A\u83B2\xB7\u77F3\u4E1C\u201D\u7684\u73CA\u838E\u968F\u4F17\u5728\u6B64\u8FC7\u51AC\uFF08\u5377\u56DB\uFF09\u3002"}}),e("stone","castle",[487,798],1,{en:"Stone",zh:"\u77F3\u5821"},["Stone waycastle","\u77F3\u9636\u5821"],{en:"The lowest of the three waycastles on the climb from the Gates of the Moon to the Eyrie. Above it the path grows steep enough that only sure-footed mules are trusted to carry riders.",zh:"\u4ECE\u6708\u95E8\u5821\u6500\u5F80\u9E70\u5DE2\u57CE\u9014\u4E2D\u4E09\u5EA7\u4E2D\u9014\u5821\u91CC\u6700\u4F4E\u7684\u4E00\u5EA7\u3002\u518D\u5F80\u4E0A\u5C71\u8DEF\u6108\u53D1\u9661\u5CED\uFF0C\u53EA\u6709\u7A33\u5065\u7684\u9AA1\u5B50\u624D\u80FD\u9A6E\u4EBA\u524D\u884C\u3002"},["arryn"],["agot"],"high"),e("snow","castle",[484,794],1,{en:"Snow",zh:"\u96EA\u5821"},["Snow waycastle"],{en:"The middle waycastle on the Giant's Lance, a small fort high enough that snow lingers around it much of the year. The path above it narrows to a knife-edge ridge exposed to the wind.",zh:"\u5DE8\u4EBA\u4E4B\u67AA\u4E0A\u7684\u7B2C\u4E8C\u5EA7\u4E2D\u9014\u5821\uFF0C\u5730\u52BF\u4E4B\u9AD8\uFF0C\u7EC8\u5E74\u5927\u534A\u65F6\u95F4\u79EF\u96EA\u4E0D\u5316\u3002\u518D\u5F80\u4E0A\uFF0C\u5C71\u8DEF\u6536\u7A84\u4E3A\u72C2\u98CE\u626B\u8FC7\u7684\u5200\u810A\u3002"},["arryn"],["agot"],"high"),e("sky","castle",[482,791],1,{en:"Sky",zh:"\u5929\u5821"},["Sky waycastle"],{en:"The last waycastle, little more than a crescent wall against the mountain directly beneath the Eyrie. Goods and some visitors are hauled the final distance up a chimney in baskets, while others climb a carved stair.",zh:"\u6700\u540E\u4E00\u5EA7\u4E2D\u9014\u5821\uFF0C\u51E0\u4E4E\u53EA\u662F\u4E00\u9053\u4F9D\u5C71\u800C\u5EFA\u7684\u534A\u6708\u5F62\u57CE\u5899\uFF0C\u6B63\u4F4D\u4E8E\u9E70\u5DE2\u57CE\u4E0B\u65B9\u3002\u8D27\u7269\u548C\u90E8\u5206\u6765\u5BA2\u8981\u5750\u540A\u7BEE\u7ECF\u7531\u4E00\u9053\u7AD6\u4E95\u62C9\u4E0A\u6700\u540E\u4E00\u6BB5\uFF0C\u5176\u4F59\u7684\u4EBA\u5219\u6500\u722C\u51FF\u5728\u5CA9\u58C1\u4E0A\u7684\u77F3\u9636\u3002"},["arryn"],["agot"],"high"),e("alyssas-tears","landmark",[476,790],1,{en:"Alyssa's Tears",zh:"\u827E\u4E3D\u838E\u4E4B\u6CEA"},["Alyssa Arryn","\u827E\u4E3D\u838E\u6CEA\u7011"],{en:"A slender waterfall that spills from the heights of the Giant's Lance near the Eyrie and turns to mist long before it reaches the valley. It is named for Alyssa Arryn, a lady who never wept for her slain family and is said to be fated to weep until her tears water the Vale.",zh:"\u4E00\u9053\u7EA4\u7EC6\u7684\u7011\u5E03\uFF0C\u4ECE\u9E70\u5DE2\u57CE\u9644\u8FD1\u7684\u5DE8\u4EBA\u4E4B\u67AA\u9AD8\u5904\u503E\u6CFB\u800C\u4E0B\uFF0C\u672A\u53CA\u8C37\u5E95\u4FBF\u5DF2\u5316\u4F5C\u6C34\u96FE\u3002\u5176\u540D\u6E90\u81EA\u827E\u4E3D\u838E\xB7\u827E\u6797\u2014\u2014\u4F20\u8BF4\u5979\u76EE\u7779\u5BB6\u4EBA\u88AB\u6740\u5374\u4ECE\u672A\u843D\u6CEA\uFF0C\u56E0\u800C\u6CE8\u5B9A\u6C38\u4E16\u54ED\u6CE3\uFF0C\u76F4\u5230\u6CEA\u6C34\u6D47\u704C\u6574\u4E2A\u8C37\u5730\u3002"},["arryn"],["agot"],"high"),e("giants-lance","mountain",[480,784],3,{en:"Giant's Lance",zh:"\u5DE8\u4EBA\u4E4B\u67AA"},["Giants Lance"],{en:"The tall peak that towers over the head of the Vale, with the Eyrie perched on its shoulder and the Gates of the Moon at its foot. Its summit is crowned with snow even in summer.",zh:"\u8038\u7ACB\u4E8E\u8C37\u5730\u5C3D\u5934\u7684\u9AD8\u5CF0\uFF0C\u9E70\u5DE2\u57CE\u8E1E\u4E8E\u5C71\u80A9\uFF0C\u6708\u95E8\u5821\u4F4D\u4E8E\u5C71\u811A\u3002\u5373\u4F7F\u5728\u590F\u65E5\uFF0C\u5CF0\u9876\u4E5F\u8986\u76D6\u7740\u79EF\u96EA\u3002"},[],["agot","maps"],"high"),e("bloody-gate","castle",[444,800],3,{en:"The Bloody Gate",zh:"\u8840\u95E8"},["Bloody Gate","\u8840\u95E8\u5173"],{en:"A fortified gate across a narrow pass where the high road enters the Vale, with towers built into the mountainsides and a bridge between them. A handful of men can hold it against a host, and its name recalls the armies broken here, from the First Men's wars to the Andal invasions.",zh:"\u9AD8\u8DEF\u8FDB\u5165\u8C37\u5730\u5904\u6A2A\u8DE8\u72ED\u7A84\u5C71\u53E3\u7684\u8981\u585E\u57CE\u95E8\uFF0C\u4E24\u4FA7\u5854\u697C\u5D4C\u5165\u5C71\u4F53\uFF0C\u4EE5\u6865\u76F8\u8FDE\u3002\u5C11\u6570\u4EBA\u4FBF\u8DB3\u4EE5\u62B5\u6321\u5927\u519B\uFF1B\u201C\u8840\u95E8\u201D\u4E4B\u540D\u8BB0\u5F55\u7740\u5386\u4EE3\u5728\u6B64\u8986\u706D\u7684\u519B\u961F\uFF0C\u4ECE\u5148\u6C11\u65F6\u4EE3\u7684\u6218\u4E89\u5230\u5B89\u8FBE\u5C14\u4EBA\u5165\u4FB5\u7686\u7136\u3002"},["arryn","waynwood"],["agot","twoiaf"],"high"),e("high-road","landmark",[438,810],2,{en:"The High Road",zh:"\u9AD8\u8DEF"},["High road","Mountain road","\u5C71\u8DEF"],{en:"The road that climbs from the riverlands near the crossroads inn through the Mountains of the Moon to the Bloody Gate. It is a hard, many-day ride through clan country, and travellers go in armed company because of the mountain clans' raids.",zh:"\u4ECE\u5341\u5B57\u8DEF\u53E3\u5BA2\u6808\u9644\u8FD1\u7684\u6CB3\u95F4\u5730\u51FA\u53D1\uFF0C\u7A7F\u8D8A\u660E\u6708\u5C71\u8109\uFF0C\u76F4\u62B5\u8840\u95E8\u7684\u9053\u8DEF\u3002\u5168\u7A0B\u8981\u5728\u5C71\u5730\u90E8\u65CF\u7684\u5730\u76D8\u4E0A\u8270\u96BE\u8DCB\u6D89\u591A\u65E5\uFF0C\u56E0\u5E38\u6709\u90E8\u65CF\u52AB\u63A0\uFF0C\u65C5\u4EBA\u591A\u7ED3\u4F34\u6301\u68B0\u800C\u884C\u3002"},[],["agot","maps"],"high"),e("mountains-of-the-moon","mountain",[500,770],4,{en:"Mountains of the Moon",zh:"\u660E\u6708\u5C71\u8109"},["\u6708\u4EAE\u5C71\u8109","\u6708\u5C71"],{en:"The great range that walls in the Vale of Arryn on the west and north, making it nearly impregnable. Its high valleys are home to the mountain clans, descendants of the First Men who were driven up into the heights by the Andals.",zh:"\u5728\u897F\u9762\u548C\u5317\u9762\u73AF\u62B1\u827E\u6797\u8C37\u7684\u5DE8\u5927\u5C71\u8109\uFF0C\u4F7F\u8C37\u5730\u51E0\u4E4E\u65E0\u61C8\u53EF\u51FB\u3002\u5C71\u4E2D\u9AD8\u8C37\u4F4F\u7740\u5404\u5C71\u5730\u90E8\u65CF\uFF0C\u4ED6\u4EEC\u662F\u5148\u6C11\u7684\u540E\u88D4\uFF0C\u5F53\u5E74\u88AB\u5B89\u8FBE\u5C14\u4EBA\u8D76\u8FDB\u4E86\u9AD8\u5C71\u3002"},[],["agot","maps","twoiaf"],"high"),e("stone-crows","landmark",[452,788],1,{en:"Stone Crows country",zh:"\u77F3\u9E26\u65CF\u9886\u5730"},["Stone Crows","\u77F3\u9E26","\u77F3\u9E26\u90E8"],{en:"The range claimed by the Stone Crows, one of the fiercest mountain clans, who prey on travellers along the high road. Their chief Shagga son of Dolf and his men became Tyrion Lannister's followers after the attack on his party. The position here is only indicative.",zh:"\u77F3\u9E26\u65CF\u7684\u5730\u76D8\u3002\u4ED6\u4EEC\u662F\u6700\u51F6\u608D\u7684\u5C71\u5730\u90E8\u65CF\u4E4B\u4E00\uFF0C\u60EF\u4E8E\u52AB\u63A0\u9AD8\u8DEF\u4E0A\u7684\u65C5\u4EBA\u3002\u5728\u88AD\u51FB\u63D0\u5229\u6602\xB7\u5170\u5C3C\u65AF\u7279\u4E00\u884C\u4E4B\u540E\uFF0C\u5176\u9996\u9886\u591A\u5C14\u592B\u4E4B\u5B50\u590F\u560E\u7387\u4F17\u8FFD\u968F\u4E86\u4ED6\u3002\u6B64\u5904\u4F4D\u7F6E\u4EC5\u4E3A\u793A\u610F\u3002"},[],["agot","acok"],"low"),e("burned-men","landmark",[468,814],1,{en:"Burned Men country",zh:"\u707C\u4EBA\u65CF\u9886\u5730"},["Burned Men","\u707C\u4EBA","\u7126\u4EBA"],{en:"The land of the Burned Men, a mountain clan who prove their courage by burning away a part of their own body. Their leader Timett son of Timett joined Tyrion with the other clans. Position indicative only.",zh:"\u707C\u4EBA\u65CF\u7684\u5730\u76D8\u3002\u8FD9\u4E2A\u5C71\u5730\u90E8\u65CF\u4EE5\u4EB2\u624B\u70E7\u53BB\u8EAB\u4F53\u67D0\u4E00\u90E8\u5206\u6765\u8BC1\u660E\u52C7\u6C14\u3002\u5176\u9996\u9886\u63D0\u9B45\u4E4B\u5B50\u63D0\u9B45\u968F\u5176\u4ED6\u90E8\u65CF\u4E00\u540C\u6295\u6548\u4E86\u63D0\u5229\u6602\u3002\u4F4D\u7F6E\u4EC5\u4E3A\u793A\u610F\u3002"},[],["agot"],"low"),e("black-ears","landmark",[448,762],1,{en:"Black Ears country",zh:"\u9ED1\u8033\u65CF\u9886\u5730"},["Black Ears","\u9ED1\u8033\u65CF"],{en:"Haunt of the Black Ears, a mountain clan who wear necklaces of the ears they cut from their enemies. Their chief Chella daughter of Cheyk rode with Tyrion. Position indicative only.",zh:"\u9ED1\u8033\u65CF\u51FA\u6CA1\u4E4B\u5730\u3002\u4ED6\u4EEC\u628A\u4ECE\u654C\u4EBA\u8EAB\u4E0A\u5272\u4E0B\u7684\u8033\u6735\u4E32\u6210\u9879\u94FE\u4F69\u6234\u3002\u9996\u9886\u67F4\u514B\u4E4B\u5973\u590F\u5361\u66FE\u968F\u63D0\u5229\u6602\u51FA\u5F81\u3002\u4F4D\u7F6E\u4EC5\u4E3A\u793A\u610F\u3002"},[],["agot"],"low"),e("moon-brothers","landmark",[474,758],1,{en:"Moon Brothers country",zh:"\u6708\u4EBA\u65CF\u9886\u5730"},["Moon Brothers","\u6708\u4E4B\u5144\u5F1F"],{en:"The range of the Moon Brothers, one of the larger mountain clans. Along with the Stone Crows and others they followed Tyrion out of the mountains during the War of the Five Kings. Position indicative only.",zh:"\u6708\u4EBA\u65CF\u7684\u5730\u76D8\uFF0C\u5C5E\u8F83\u5927\u7684\u5C71\u5730\u90E8\u65CF\u4E4B\u4E00\u3002\u4E94\u738B\u4E4B\u6218\u671F\u95F4\uFF0C\u4ED6\u4EEC\u4E0E\u77F3\u9E26\u65CF\u7B49\u90E8\u65CF\u4E00\u540C\u8FFD\u968F\u63D0\u5229\u6602\u51FA\u5C71\u3002\u4F4D\u7F6E\u4EC5\u4E3A\u793A\u610F\u3002"},[],["agot","acok"],"low"),e("milk-snakes","landmark",[470,821],1,{en:"Milk Snakes country",zh:"\u4E73\u86C7\u65CF\u9886\u5730"},["Milk Snakes","\u4E73\u86C7\u65CF"],{en:"One of the lesser mountain clans, named among the raiders who harass the high road. The books say little about them beyond their name and their feuds with the other clans.",zh:"\u8F83\u5C0F\u7684\u5C71\u5730\u90E8\u65CF\u4E4B\u4E00\uFF0C\u5E38\u88AB\u5217\u4E3A\u4FB5\u6270\u9AD8\u8DEF\u7684\u52AB\u532A\u3002\u4E66\u4E2D\u5BF9\u4ED6\u4EEC\u7740\u58A8\u4E0D\u591A\uFF0C\u53EA\u63D0\u53CA\u5176\u540D\u53F7\u4EE5\u53CA\u4E0E\u5176\u4ED6\u90E8\u65CF\u7684\u4E16\u4EC7\u3002"},[],["agot"],"low"),e("painted-dogs","landmark",[502,752],1,{en:"Painted Dogs country",zh:"\u5F69\u72AC\u65CF\u9886\u5730"},["Painted Dogs","\u5F69\u72AC\u65CF"],{en:"Territory of the Painted Dogs, another of the small mountain clans of the Mountains of the Moon. Like the Milk Snakes they are known mostly by name. Position indicative only.",zh:"\u5F69\u72AC\u65CF\u7684\u5730\u76D8\uFF0C\u4E5F\u662F\u660E\u6708\u5C71\u8109\u4E2D\u7684\u5C0F\u578B\u5C71\u5730\u90E8\u65CF\u4E4B\u4E00\u3002\u4E0E\u4E73\u86C7\u65CF\u4E00\u6837\uFF0C\u4E66\u4E2D\u51E0\u4E4E\u53EA\u7559\u4E0B\u5176\u540D\u53F7\u3002\u4F4D\u7F6E\u4EC5\u4E3A\u793A\u610F\u3002"},[],["agot"],"low"),e("runestone","castle",[598,780],3,{en:"Runestone",zh:"\u7B26\u6587\u77F3\u57CE"},["Runestone castle","\u7B26\u77F3\u57CE"],{en:"The ancient seat of House Royce near the Vale's eastern coast, named for a great stone carved with runes of the First Men. The Royces were kings in the Vale before the Andals and still keep the bronze armour of their forefathers.",zh:"\u7F57\u4F0A\u65AF\u5BB6\u65CF\u7684\u53E4\u8001\u5C45\u57CE\uFF0C\u9760\u8FD1\u8C37\u5730\u4E1C\u6D77\u5CB8\uFF0C\u5F97\u540D\u4E8E\u4E00\u5757\u523B\u6709\u5148\u6C11\u7B26\u6587\u7684\u5DE8\u77F3\u3002\u5B89\u8FBE\u5C14\u4EBA\u5230\u6765\u4E4B\u524D\uFF0C\u7F57\u4F0A\u65AF\u5BB6\u65CF\u66FE\u662F\u8C37\u5730\u4E4B\u738B\uFF0C\u81F3\u4ECA\u4ECD\u73CD\u85CF\u5148\u7956\u7684\u9752\u94DC\u94E0\u7532\u3002"},["royce"],["agot","twoiaf"],"medium"),e("redfort","castle",[520,812],2,{en:"Redfort",zh:"\u96F7\u5FB7\u4F5B\u57CE"},["Red Fort","\u7EA2\u5821\u57CE"],{en:"Seat of House Redfort, in the southern Vale between the Eyrie and the sea. Its lord Horton Redfort is one of the Vale lords who weigh in on who should guard the young Lord Arryn.",zh:"\u96F7\u5FB7\u4F5B\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u8C37\u5730\u5357\u90E8\uFF0C\u4ECB\u4E8E\u9E70\u5DE2\u57CE\u4E0E\u5927\u6D77\u4E4B\u95F4\u3002\u9886\u4E3B\u970D\u987F\xB7\u96F7\u5FB7\u4F5B\u662F\u5728\u5E74\u5E7C\u7684\u827E\u6797\u516C\u7235\u76D1\u62A4\u95EE\u9898\u4E0A\u4E3E\u8DB3\u8F7B\u91CD\u7684\u8C37\u5730\u8BF8\u4FAF\u4E4B\u4E00\u3002"},["redfort"],["agot","affc","maps"],"medium"),e("ironoaks","castle",[534,792],2,{en:"Ironoaks",zh:"\u94C1\u6A61\u5821"},["Iron Oaks"],{en:"Seat of House Waynwood, among the oak woods in the heart of the Vale. Its lady, Anya Waynwood, is one of the most respected voices among the Vale lords.",zh:"\u97E6\u4F0D\u5FB7\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u4E8E\u8C37\u5730\u8179\u5730\u7684\u6A61\u6811\u6797\u95F4\u3002\u57CE\u4E3B\u5B89\u96C5\xB7\u97E6\u4F0D\u5FB7\u592B\u4EBA\u662F\u8C37\u5730\u8BF8\u4FAF\u4E2D\u6700\u53D7\u656C\u91CD\u7684\u4EBA\u7269\u4E4B\u4E00\u3002"},["waynwood"],["agot","affc","maps"],"medium"),e("hearts-home","castle",[520,764],2,{en:"Heart's Home",zh:"\u5FC3\u4E4B\u5BB6"},["Hearts Home","\u5BB6\u5FC3\u5821"],{en:"Seat of House Corbray, in the northern part of the Vale toward the mountains. The Corbrays keep the Valyrian steel sword Lady Forlorn, carried in the books by the hot-tempered Ser Lyn Corbray.",zh:"\u79D1\u5E03\u745E\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u8C37\u5730\u5317\u90E8\u9760\u5C71\u4E4B\u5904\u3002\u79D1\u5E03\u745E\u5BB6\u65CF\u85CF\u6709\u74E6\u96F7\u5229\u4E9A\u94A2\u5251\u201C\u5B64\u5973\u201D\uFF0C\u4E66\u4E2D\u7531\u813E\u6C14\u66B4\u70C8\u7684\u6797\u6069\xB7\u79D1\u5E03\u745E\u7235\u58EB\u4F69\u5E26\u3002"},["corbray"],["agot","affc","maps"],"medium"),e("longbow-hall","castle",[574,758],2,{en:"Longbow Hall",zh:"\u957F\u5F13\u5385"},["Longbow"],{en:"Seat of House Hunter, in the north-eastern Vale towards the Fingers. Its old lord Eon Hunter is among the Vale lords present at the Eyrie during Tyrion's trial by combat.",zh:"\u4EA8\u7279\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u8C37\u5730\u4E1C\u5317\u90E8\uFF0C\u9760\u8FD1\u4E94\u6307\u534A\u5C9B\u3002\u8001\u9886\u4E3B\u4F0A\u6602\xB7\u4EA8\u7279\u66FE\u5728\u9E70\u5DE2\u57CE\u76EE\u7779\u63D0\u5229\u6602\u7684\u51B3\u6597\u5BA1\u5224\u3002"},["hunter"],["agot","affc","maps"],"medium"),e("strongsong","castle",[498,742],2,{en:"Strongsong",zh:"\u5F3A\u6B4C\u57CE"},["Strong Song"],{en:"Seat of House Belmore, in the north of the Vale between the mountains and the Bite. Its lord Benedar Belmore is one of the Lords Declarant who band together after Lysa Arryn's death.",zh:"\u8D1D\u5C14\u6469\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u8C37\u5730\u5317\u90E8\uFF0C\u4ECB\u4E8E\u5C71\u8109\u4E0E\u54AC\u4EBA\u6E7E\u4E4B\u95F4\u3002\u9886\u4E3B\u73ED\u5C3C\u8FBE\xB7\u8D1D\u5C14\u6469\u662F\u83B1\u838E\xB7\u827E\u6797\u6B7B\u540E\u7ED3\u76DF\u7684\u201C\u7533\u8BC9\u8BF8\u4FAF\u201D\u4E4B\u4E00\u3002"},["belmore"],["affc","maps"],"medium"),e("ninestars","castle",[548,724],2,{en:"Ninestars",zh:"\u4E5D\u661F\u57CE"},["Nine Stars"],{en:"Seat of House Templeton, near the Vale's northern coast on the Bite. Its knight, Ser Symond Templeton, joins the other Lords Declarant in A Feast for Crows.",zh:"\u5766\u5E15\u987F\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u9760\u8FD1\u8C37\u5730\u6FD2\u4E34\u54AC\u4EBA\u6E7E\u7684\u5317\u90E8\u6D77\u5CB8\u3002\u5728\u5377\u56DB\u4E2D\uFF0C\u5176\u4E3B\u4EBA\u201C\u4E5D\u661F\u9A91\u58EB\u201D\u897F\u8499\xB7\u5766\u5E15\u987F\u7235\u58EB\u52A0\u5165\u4E86\u7533\u8BC9\u8BF8\u4FAF\u7684\u884C\u5217\u3002"},["templeton"],["affc","maps"],"medium"),e("old-anchor","castle",[604,764],1,{en:"Old Anchor",zh:"\u53E4\u951A\u57CE"},["Oldanchor"],{en:"Seat of House Melcolm on the Vale's eastern coast, near the base of the Fingers. Little is told of it beyond its name and its lords' loyalty to the Arryns.",zh:"\u6885\u5C14\u79D1\u59C6\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u8C37\u5730\u4E1C\u6D77\u5CB8\u3001\u4E94\u6307\u534A\u5C9B\u6839\u90E8\u9644\u8FD1\u3002\u4E66\u4E2D\u9664\u4E86\u540D\u79F0\u548C\u5176\u9886\u4E3B\u6548\u5FE0\u827E\u6797\u5BB6\u65CF\u5916\uFF0C\u6240\u8FF0\u751A\u5C11\u3002"},["melcolm"],["twoiaf","maps"],"low"),e("snakewood","castle",[474,738],1,{en:"The Snakewood",zh:"\u86C7\u6728\u57CE"},["Snakewood"],{en:"Seat of House Lynderly, on the Vale's north-western coast where the mountains run down to the Bite.",zh:"\u6797\u5FB7\u5229\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u8C37\u5730\u897F\u5317\u6D77\u5CB8\uFF0C\u660E\u6708\u5C71\u8109\u5728\u6B64\u5EF6\u4F38\u5165\u54AC\u4EBA\u6E7E\u3002"},["lynderly"],["affc","maps"],"low"),e("coldwater-burn","castle",[522,728],1,{en:"Coldwater Burn",zh:"\u5BD2\u6C34\u6EAA\u57CE"},["Coldwater"],{en:"Seat of House Coldwater, near the Vale's northern shore on the Bite. It is named in histories of the Vale but plays no part in the main story.",zh:"\u5BD2\u6C34\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u9760\u8FD1\u8C37\u5730\u6FD2\u4E34\u54AC\u4EBA\u6E7E\u7684\u5317\u5CB8\u3002\u8C37\u5730\u53F2\u7C4D\u4E2D\u63D0\u5230\u8FC7\u5B83\uFF0C\u4F46\u5728\u6B63\u4F20\u6545\u4E8B\u91CC\u5E76\u65E0\u620F\u4EFD\u3002"},["coldwater"],["twoiaf","maps"],"low"),e("grey-glen","castle",[448,774],1,{en:"Grey Glen",zh:"\u7070\u8C37"},["Greyglen"],{en:"Seat of House Tollett, a minor Vale house best known through Dolorous Edd Tollett of the Night's Watch. Its exact position in the Vale is not given; it is placed here among the western valleys as a guess.",zh:"\u6258\u52D2\u7279\u5BB6\u65CF\u7684\u5C45\u57CE\u3002\u8FD9\u4E2A\u8C37\u5730\u5C0F\u5BB6\u65CF\u6700\u4E3A\u4EBA\u77E5\u7684\u6210\u5458\uFF0C\u662F\u5B88\u591C\u4EBA\u4E2D\u7684\u201C\u5FE7\u90C1\u7684\u827E\u8FEA\u201D\xB7\u6258\u52D2\u7279\u3002\u4E66\u4E2D\u672A\u7ED9\u51FA\u786E\u5207\u65B9\u4F4D\uFF0C\u6B64\u5904\u6682\u7F6E\u4E8E\u8C37\u5730\u897F\u90E8\u5C71\u8C37\u4E4B\u4E2D\u3002"},["tollett"],["twoiaf"],"low"),e("newkeep","castle",[548,776],1,{en:"Newkeep",zh:"\u65B0\u5792"},["New Keep"],{en:"Seat of House Hersy, a lesser house of the Vale. Its location within the valley is not specified, so this position is a placeholder.",zh:"\u8D6B\u5E0C\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u8BE5\u5BB6\u65CF\u662F\u8C37\u5730\u7684\u5C0F\u5BB6\u65CF\u3002\u4E66\u4E2D\u672A\u8BF4\u660E\u5176\u5728\u8C37\u5730\u4E2D\u7684\u5177\u4F53\u4F4D\u7F6E\uFF0C\u6B64\u5904\u4EC5\u4E3A\u6682\u5B9A\u3002"},["hersy"],["twoiaf"],"low"),e("gull-tower","castle",[542,818],1,{en:"Gull Tower",zh:"\u6D77\u9E25\u5854"},["Gulltower"],{en:"Seat of House Shett, a tower near Gulltown on the Vale's southern coast. It stands in the shadow of the Graftons' port city.",zh:"\u96EA\u7279\u5BB6\u65CF\u7684\u5C45\u6240\uFF0C\u6D77\u9E25\u9547\u9644\u8FD1\u3001\u8C37\u5730\u5357\u90E8\u6D77\u5CB8\u8FB9\u7684\u4E00\u5EA7\u5854\u697C\uFF0C\u4F4D\u4E8E\u845B\u62C9\u592B\u987F\u5BB6\u65CF\u6E2F\u57CE\u7684\u9634\u5F71\u4E4B\u4E0B\u3002"},["shett"],["twoiaf"],"low"),e("wickenden","castle",[588,714],1,{en:"Wickenden",zh:"\u7EF4\u80AF\u767B"},[],{en:"A castle shown on official maps of the Vale near the base of the Fingers on the Bite coast. Neither the novels nor the companion say much about it or its holders.",zh:"\u5B98\u65B9\u8C37\u5730\u5730\u56FE\u4E0A\u6807\u51FA\u7684\u4E00\u5EA7\u57CE\u5821\uFF0C\u4F4D\u4E8E\u4E94\u6307\u534A\u5C9B\u6839\u90E8\u3001\u54AC\u4EBA\u6E7E\u6CBF\u5CB8\u3002\u5C0F\u8BF4\u548C\u8BBE\u5B9A\u96C6\u90FD\u51E0\u4E4E\u6CA1\u6709\u63D0\u53CA\u5B83\u6216\u5176\u4E3B\u4EBA\u3002"},[],["maps"],"low"),e("the-fingers","landmark",[624,726],3,{en:"The Fingers",zh:"\u4E94\u6307\u534A\u5C9B"},["Fingers","\u4E94\u6307"],{en:`A ragged peninsula of narrow, windswept spits of land reaching from the Vale into the Narrow Sea. It is poor country of rocks, sheep and small holdfasts, and the source of Petyr "Littlefinger" Baelish's mocking nickname. Tradition holds that the Andals first came ashore here when they crossed from Essos.`,zh:"\u4ECE\u8C37\u5730\u4F38\u5165\u72ED\u6D77\u7684\u4E00\u7247\u7834\u788E\u534A\u5C9B\uFF0C\u7531\u51E0\u9053\u72ED\u957F\u3001\u98CE\u5439\u96E8\u6253\u7684\u5CAC\u89D2\u7EC4\u6210\u3002\u8FD9\u91CC\u662F\u4E71\u77F3\u3001\u7F8A\u7FA4\u548C\u5C0F\u5C0F\u5821\u5792\u7684\u8D2B\u7620\u4E4B\u5730\uFF0C\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\u7684\u7EF0\u53F7\u201C\u5C0F\u6307\u5934\u201D\u4FBF\u7531\u6B64\u800C\u6765\u3002\u76F8\u4F20\u5B89\u8FBE\u5C14\u4EBA\u6E21\u6D77\u800C\u6765\u65F6\uFF0C\u6700\u65E9\u4FBF\u5728\u6B64\u767B\u9646\u3002"},["baelish"],["agot","maps"],"high"),e("baelish-holdfast","castle",[630,688],1,{en:"Baelish holdfast",zh:"\u8D1D\u91CC\u5E2D\u5BB6\u65CF\u5854\u5821"},["Petyr Baelish's tower","Littlefinger's holdfast","\u5C0F\u6307\u5934\u7684\u5854\u697C"],{en:"The tiny ancestral holding of House Baelish on the smallest of the Fingers: a single stone tower with a few acres of stony ground and a shepherd or two. Petyr speaks of it with self-mockery; it marks how low his family started.",zh:"\u8D1D\u91CC\u5E2D\u5BB6\u65CF\u5728\u4E94\u6307\u534A\u5C9B\u6700\u5C0F\u4E00\u6307\u4E0A\u7684\u7956\u4F20\u9886\u5730\uFF1A\u4E00\u5EA7\u5B64\u96F6\u96F6\u7684\u77F3\u5854\u3001\u51E0\u4EA9\u4E71\u77F3\u5730\uFF0C\u5916\u52A0\u4E00\u4E24\u4E2A\u7267\u7F8A\u4EBA\u3002\u57F9\u63D0\u5C14\u63D0\u8D77\u5B83\u65F6\u5E38\u5E26\u81EA\u5632\u2014\u2014\u5B83\u6B63\u6807\u660E\u4E86\u8FD9\u4E2A\u5BB6\u65CF\u7684\u51FA\u8EAB\u4F55\u7B49\u5351\u5FAE\u3002"},["baelish"],["agot","affc"],"medium"),e("the-paps","mountain",[640,722],1,{en:"The Paps",zh:"\u4E73\u5CF0"},["Paps"],{en:"A pair of rounded hills on the Fingers, named on maps of the Vale for their shape. They serve as a landmark for ships along this bare coast.",zh:"\u4E94\u6307\u534A\u5C9B\u4E0A\u4E00\u5BF9\u6D51\u5706\u7684\u5C71\u4E18\uFF0C\u56E0\u5F62\u72B6\u800C\u5F97\u540D\uFF0C\u89C1\u4E8E\u8C37\u5730\u5730\u56FE\u3002\u5728\u8FD9\u7247\u5149\u79C3\u79C3\u7684\u6D77\u5CB8\u4E0A\uFF0C\u5B83\u4EEC\u662F\u8FC7\u5F80\u8239\u53EA\u7684\u5730\u6807\u3002"},[],["maps"],"low"),e("pebble","island",[668,700],1,{en:"Pebble",zh:"\u5375\u77F3\u5C9B"},[],{en:"A small island off the Fingers, seat of the minor House Pryor. It is little more than a name in the companion histories.",zh:"\u4E94\u6307\u534A\u5C9B\u5916\u6D77\u7684\u4E00\u5EA7\u5C0F\u5C9B\uFF0C\u5C0F\u5BB6\u65CF\u666E\u745E\u5C14\u5BB6\u65CF\u7684\u5C01\u5730\u3002\u5728\u8BBE\u5B9A\u96C6\u4E2D\u5B83\u51E0\u4E4E\u53EA\u662F\u4E00\u4E2A\u540D\u5B57\u3002"},["pryor"],["twoiaf"],"low"),e("witch-isle","island",[532,694],1,{en:"Witch Isle",zh:"\u5973\u5DEB\u5C9B"},["Witch Island"],{en:"An island in the Bite off the Vale's northern coast, seat of House Upcliff. Its name hints at old tales, but the books give few details.",zh:"\u8C37\u5730\u5317\u90E8\u5916\u6D77\u3001\u54AC\u4EBA\u6E7E\u4E2D\u7684\u4E00\u5EA7\u5C9B\u5C7F\uFF0C\u4E0A\u5D16\u5BB6\u65CF\u7684\u5C01\u5730\u3002\u5C9B\u540D\u6697\u793A\u7740\u53E4\u8001\u7684\u4F20\u8BF4\uFF0C\u4F46\u4E66\u4E2D\u7EC6\u8282\u5BE5\u5BE5\u3002"},["upcliff"],["twoiaf","maps"],"low"),e("three-sisters","island",[562,646],3,{en:"The Three Sisters",zh:"\u4E09\u59D0\u59B9\u7FA4\u5C9B"},["Sisters","Three Sisters","\u4E09\u59D0\u59B9"],{en:"Three rocky islands in the Bite, nominally part of the Vale but long a haunt of wreckers, smugglers and pirates. Their lords answer to the Sunderlands and, in name, to the Eyrie, though Sistermen have little love for either.",zh:"\u54AC\u4EBA\u6E7E\u4E2D\u7684\u4E09\u5EA7\u5CA9\u5C9B\uFF0C\u540D\u4E49\u4E0A\u5C5E\u4E8E\u8C37\u5730\uFF0C\u4F46\u957F\u4E45\u4EE5\u6765\u662F\u8BF1\u8239\u52AB\u63A0\u8005\u3001\u8D70\u79C1\u72AF\u548C\u6D77\u76D7\u7684\u5DE2\u7A74\u3002\u5C9B\u4E0A\u9886\u4E3B\u542C\u547D\u4E8E\u6851\u5FB7\u5170\u5BB6\u65CF\uFF0C\u540D\u4E49\u4E0A\u4E5F\u6548\u5FE0\u9E70\u5DE2\u57CE\uFF0C\u7136\u800C\u59D0\u59B9\u5C9B\u6C11\u5BF9\u4E8C\u8005\u90FD\u8C08\u4E0D\u4E0A\u7231\u6234\u3002"},["sunderland","borrell","longthorpe","torrent"],["adwd","twoiaf"],"high"),e("sweetsister","island",[546,632],2,{en:"Sweetsister",zh:"\u751C\u59D0\u59B9\u5C9B"},["Sweet Sister"],{en:"The westernmost of the Three Sisters and home of its chief town, Sisterton. It is held by House Borrell.",zh:"\u4E09\u59D0\u59B9\u7FA4\u5C9B\u4E2D\u6700\u897F\u9762\u7684\u4E00\u5EA7\uFF0C\u5C9B\u4E0A\u6709\u7FA4\u5C9B\u7684\u4E3B\u8981\u57CE\u9547\u59D0\u59B9\u9547\uFF0C\u7531\u6CE2\u745E\u5C14\u5BB6\u65CF\u7EDF\u6CBB\u3002"},["borrell"],["adwd"],"medium"),e("longsister","island",[570,656],2,{en:"Longsister",zh:"\u957F\u59D0\u59B9\u5C9B"},["Long Sister"],{en:"The largest of the Three Sisters, a long ridge of an island ruled by House Longthorpe.",zh:"\u4E09\u59D0\u59B9\u7FA4\u5C9B\u4E2D\u6700\u5927\u7684\u4E00\u5EA7\uFF0C\u72ED\u957F\u5982\u5C71\u810A\uFF0C\u7531\u6717\u7D22\u666E\u5BB6\u65CF\u7EDF\u6CBB\u3002"},["longthorpe"],["adwd","twoiaf"],"medium"),e("littlesister","island",[582,626],2,{en:"Littlesister",zh:"\u5C0F\u59D0\u59B9\u5C9B"},["Little Sister"],{en:"The smallest of the Three Sisters, held by House Torrent.",zh:"\u4E09\u59D0\u59B9\u7FA4\u5C9B\u4E2D\u6700\u5C0F\u7684\u4E00\u5EA7\uFF0C\u7531\u6258\u4F26\u7279\u5BB6\u65CF\u7EDF\u6CBB\u3002"},["torrent"],["adwd","twoiaf"],"medium"),e("sisterton","town",[548,640],2,{en:"Sisterton",zh:"\u59D0\u59B9\u9547"},["Sister Town"],{en:"A grey, smelly harbour town on Sweetsister, the chief settlement of the Three Sisters. It lives on fishing, smuggling and the salvage of ships wrecked on the islands.",zh:"\u751C\u59D0\u59B9\u5C9B\u4E0A\u4E00\u5EA7\u7070\u6697\u8165\u81ED\u7684\u6E2F\u9547\uFF0C\u662F\u4E09\u59D0\u59B9\u7FA4\u5C9B\u7684\u4E3B\u8981\u805A\u843D\u3002\u9547\u6C11\u9760\u6355\u9C7C\u3001\u8D70\u79C1\u548C\u6253\u635E\u5728\u5C9B\u8FB9\u89E6\u7901\u7684\u8239\u53EA\u4E3A\u751F\u3002"},["borrell"],["adwd"],"high",{spoiler:{en:"Davos Seaworth's ship puts in here and he is brought before Lord Godric Borrell on his way to White Harbor (A Dance with Dragons).",zh:"\u6234\u4F5B\u65AF\xB7\u5E2D\u6E25\u65AF\u524D\u5F80\u767D\u6E2F\u9014\u4E2D\u6240\u4E58\u7684\u8239\u5728\u6B64\u9760\u5CB8\uFF0C\u4ED6\u88AB\u5E26\u53BB\u9762\u89C1\u6208\u5FB7\u745E\xB7\u6CE2\u745E\u5C14\u4F2F\u7235\uFF08\u5377\u4E94\uFF09\u3002"}}),e("night-lamp","landmark",[542,634],1,{en:"The Night Lamp",zh:"\u591C\u706F\u5854"},["Night Lamp"],{en:"The keep of the Borrells above Sisterton harbour, topped by a beacon fire that guides ships into port. The islands themselves have a long reputation for wrecking and piracy.",zh:"\u6CE2\u745E\u5C14\u5BB6\u65CF\u4FEF\u77B0\u59D0\u59B9\u9547\u6E2F\u53E3\u7684\u5854\u5821\uFF0C\u5854\u9876\u71C3\u7740\u5F15\u5BFC\u8239\u53EA\u5165\u6E2F\u7684\u70FD\u706B\u3002\u4E09\u59D0\u59B9\u7FA4\u5C9B\u672C\u8EAB\u5219\u5411\u6765\u4EE5\u8BF1\u8239\u52AB\u63A0\u548C\u6D77\u76D7\u884C\u5F84\u95FB\u540D\u3002"},["borrell"],["adwd"],"medium")]};export{c as default};
